rectangle-rule.pseudocode:
def rectangle_rule(f, a, b, n, mode='mid'):
    h = (b - a) / n  # 소구간 폭
    total = 0.0
    for i in range(n):
        x_left = a + i * h
        if mode == 'left':
            x = x_left  # 좌 끝점: 오차 O(h)
        elif mode == 'right':
            x = x_left + h  # 우 끝점: 오차 O(h)
        else:
            x = x_left + h / 2  # 중점: 오차 O(h²)
        total += f(x)
    return total * h  # 직사각형 넓이의 합

recursion.pseudocode:
def fact(n):
    if n <= 1:  # 기저 조건
        return 1
    return n * fact(n - 1)  # 재귀 조건

def fib(n, memo=None):  # 중복 호출 제거 (메모이제이션)
    if memo is None:
        memo = {}
    if n <= 1:
        return n
    if n not in memo:
        memo[n] = fib(n - 1, memo) + fib(n - 2, memo)
    return memo[n]

redo.pseudocode:
def redo(log, db, ckpt_lsn):
    committed = {r.txn for r in log if r.type == 'COMMIT'}
    for r in log:  # 기록 순서(순방향)대로
        if r.lsn < ckpt_lsn or r.type != 'UPDATE':
            continue
        if r.txn not in committed:
            continue  # 미커밋 → UNDO 단계에서 처리
        page = db.page(r.page_id)
        if page.lsn >= r.lsn:
            continue  # 이미 반영됨 → 중복 적용 방지
        page.write(r.item, r.after)  # 변경 후 값 반영
        page.lsn = r.lsn

reference-counting.pseudocode:
def inc_ref(obj):
    obj.rc += 1

def dec_ref(obj):
    obj.rc -= 1
    if obj.rc == 0:  # 더 이상 참조 없음
        for child in obj.refs:
            dec_ref(child)  # 연쇄 해제
        free(obj)  # 즉시 회수
# 한계: A↔B 순환 참조는 rc가 0이 안 됨

region-code.pseudocode:
TOP, BOTTOM, RIGHT, LEFT = 8, 4, 2, 1  # 상·하·우·좌

def outcode(x, y, xmin, ymin, xmax, ymax):
    code = 0  # 0000 = 윈도우 내부
    if y > ymax:
        code |= TOP
    elif y < ymin:
        code |= BOTTOM
    if x > xmax:
        code |= RIGHT
    elif x < xmin:
        code |= LEFT
    return code

def trivial_test(c1, c2):
    if (c1 | c2) == 0:
        return 'accept'  # 두 끝점 모두 내부
    if (c1 & c2) != 0:
        return 'reject'  # 같은 외부 영역에 걸침
    return 'clip'  # 1인 비트의 경계와 교점 계산

