remote-proxy.pseudocode:
class Subject:  # 공통 인터페이스
    def request(self, x): raise NotImplementedError

class RealSubject(Subject):  # 원격 서버에 존재
    def request(self, x):
        return x * 2

class RemoteProxy(Subject):  # 클라이언트 측 로컬 대리자
    def __init__(self, endpoint):
        self.endpoint = endpoint

    def request(self, x):
        msg = serialize({'op': 'request', 'arg': x})
        try:
            raw = send(self.endpoint, msg, timeout=3)
        except Timeout:  # 네트워크 지연·장애 처리
            raise RemoteError('원격 호출 실패')
        return deserialize(raw)['result']

def client(subject):
    # 로컬 객체인지 프록시인지 모름(위치 투명성)
    return subject.request(21)

replace-conditional-with-polymorphism.pseudocode:
# Before: 타입 코드 분기 (Switch Statements 스멜)
def speed(bird):
    if bird.type == 'EUROPEAN':
        return base_speed()
    elif bird.type == 'AFRICAN':
        return base_speed() - load() * bird.coconuts
    elif bird.type == 'NORWEGIAN_BLUE':
        return 0 if bird.nailed else bird.voltage * 10

# After: 각 분기를 서브클래스 오버라이드로 이동
class Bird:
    def speed(self): raise NotImplementedError

class European(Bird):
    def speed(self): return base_speed()

class African(Bird):
    def speed(self):
        return base_speed() - load() * self.coconuts

class NorwegianBlue(Bird):
    def speed(self):
        return 0 if self.nailed else self.voltage * 10

# 호출부는 타입 검사 없이 bird.speed()만 호출

reservoir-sampling.pseudocode:
def reservoir_sample(stream, k):
    res = []
    for i, x in enumerate(stream, start=1):
        if i <= k:
            res.append(x)  # 처음 k개는 그대로 저장
        else:
            j = randint(1, i)  # 1..i 균등 난수
            if j <= k:  # 확률 k/i로 채택
                res[j - 1] = x  # 저수지의 임의 원소와 교체
    return res  # 각 원소 최종 선택 확률 = k/n

resolution-refutation.pseudocode:
def negate(lit):  # 리터럴 'P' ↔ '~P'
    return lit[1:] if lit.startswith('~') else '~' + lit

def resolve(c1, c2):  # 상보 리터럴 하나를 소거
    return [(c1 - {l}) | (c2 - {negate(l)})
            for l in c1 if negate(l) in c2]

def refute(kb, goal):  # kb: frozenset 절들의 집합
    clauses = set(kb) | {frozenset([negate(goal)])}
    while True:
        new = set()
        for c1 in clauses:
            for c2 in clauses:
                for r in resolve(c1, c2):
                    if not r:
                        return True  # 빈 절 → 모순 → 증명
                    new.add(frozenset(r))
        if new <= clauses:
            return False  # 새 절 없음 → 증명 실패
        clauses |= new

resource-allocation-graph.pseudocode:
def has_cycle(graph):  # graph: {정점: [다음 정점]}
    WHITE, GRAY, BLACK = 0, 1, 2
    color = {v: WHITE for v in graph}

    def dfs(v):
        color[v] = GRAY  # 탐색 중
        for w in graph.get(v, []):
            c = color.get(w, WHITE)
            if c == GRAY:
                return True  # 역방향 간선 = 사이클
            if c == WHITE and dfs(w):
                return True
        color[v] = BLACK  # 탐색 완료
        return False

    return any(color[v] == WHITE and dfs(v) for v in graph)

